// Helpers for the pre-built county map (lib/data/kenyaCountiesMap.json,
// generated by scripts/build-county-map.mjs).
import mapData from "@/lib/data/kenyaCountiesMap.json";

export type MapCounty = { id: string; name: string; iso: string; d: string; cx: number; cy: number; area: number };

export const countyMap = mapData as {
  source: string;
  width: number;
  height: number;
  projection: { scale: number; translate: [number, number] };
  counties: MapCounty[];
};

/** Web Mercator, same settings the map was drawn with: lon/lat in degrees -> SVG units. */
export function project(lon: number, lat: number): [number, number] {
  const { scale, translate: [tx, ty] } = countyMap.projection;
  const λ = (lon * Math.PI) / 180;
  const φ = (lat * Math.PI) / 180;
  return [scale * λ + tx, ty - scale * Math.log(Math.tan(Math.PI / 4 + φ / 2))];
}

// "M x yLx y…Z" -> rings of points
const ringCache = new Map<string, [number, number][][]>();
function rings(d: string) {
  let r = ringCache.get(d);
  if (!r) {
    r = d.split("Z").filter(Boolean).map((part) =>
      part.replace(/^M/, "").split("L").map((p) => p.trim().split(" ").map(Number) as [number, number]));
    ringCache.set(d, r);
  }
  return r;
}

// even-odd point-in-polygon across all rings of a county (handles holes and islands)
function contains(d: string, x: number, y: number) {
  let inside = false;
  for (const ring of rings(d)) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i], [xj, yj] = ring[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
  }
  return inside;
}

/** County id (c-001…c-047) for a GPS position, or null when it is outside Kenya. */
export function countyAt(lon: number, lat: number): string | null {
  const [x, y] = project(lon, lat);
  return countyMap.counties.find((c) => contains(c.d, x, y))?.id ?? null;
}
